class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        max_w = 0

        for a, b, w in edges:
            rev[b].append((a, w))
            max_w = max(max_w, w)

        def can(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1

            while stack:
                node = stack.pop()
                for nxt, w in rev[node]:
                    if w <= limit and not seen[nxt]:
                        seen[nxt] = True
                        count += 1
                        stack.append(nxt)

            return count == n

        if not can(max_w):
            return -1

        left, right = 1, max_w
        while left < right:
            mid = (left + right) // 2
            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left

